
#include <iostream>
#include <vector>
#include <string>

#include "MemoryAddressGenerator.h"
#include "MemoryCoalescer.h"

using namespace std;

// Display the addresses generated by a warp
void printAddresses(const vector<uint64_t>& addresses) {

    for (int i = 0; i < static_cast<int>(addresses.size()); i++) {
        cout << "Thread " << i
             << " -> Address " << addresses[i] << "\n";
    }
}

// Display coalesced memory blocks
void printBlocks(const vector<uint64_t>& blocks) {

    cout << "Unique memory blocks: " << blocks.size() << "\n";

    cout << "Block starting addresses: ";

    for (uint64_t block : blocks) {
        cout << block << " ";
    }

    cout << "\n";
}

// Run one memory access experiment
void runExperiment(
    const string& pattern,
    const vector<uint64_t>& addresses
) {
    cout << "\n========== " << pattern << " ==========\n";

    printAddresses(addresses);

    auto blocks = coalesceAddresses(addresses, BLOCK_SIZE);

    cout << "\n";

    printBlocks(blocks);
}

int main() {

    // Experiment 1: Contiguous access
    auto contiguous = generateAddresses(0, 0, 1, 4);

    runExperiment("CONTIGUOUS", contiguous);

    // Experiment 2: Stride 4
    auto strided4 = generateAddresses(0, 0, 4, 4);

    runExperiment("STRIDE 4", strided4);

    // Experiment 3: Stride 32
    auto strided32 = generateAddresses(0, 0, 32, 4);

    runExperiment("STRIDE 32", strided32);

    // Experiment 4: Misaligned contiguous access
    auto misaligned = generateAddresses(0, 4, 1, 4);

    runExperiment("MISALIGNED", misaligned);

    // Experiment 5: Random access
    auto randomAccess = generateRandomAddresses(0, 1024, 4);

    runExperiment("RANDOM", randomAccess);

    return 0;
}
